my $result = <[coding.helper.format_duration]>->( $slot, $log_level );

return TRUE if $result;
return FALSE;

my $threads = <inference.backend.cpu.threads> // 8;
$threads = 24 if $threads > 24;    ## clamp : configured values past 24 wedge the backend
<[base.logs]>->( 2, 'threads : %s', $threads );

## optional call : silent skip when the helper is not compiled in this zenka
my $result = <[base.code.call_optional]>->(
    qw| coding.helper.write_json |, $model_path
);

my $task_id = shift // return FALSE;
my $state = <coding.tasks>->{$task_id}{'state'} // qw| unknown |;

return TRUE if $state eq qw| active |;
return FALSE;

## deferred timer [ non-blocking, handler runs on the event loop ]
<[event.add_timer]>->(
    {   'after'   => 1.3,
        'handler' => qw| coding.handler.poll_server |,
        'data'    => { 'id' => $session_id },
    }
);

my $job_retry_limit = <coding.cfg.job_retry_limit> // 3;

## missing job id : log and bail [ false-mode reply ]
unless ( defined $job_id and length $job_id ) {
    <[base.logs]>->( 0, '%s called without a job id', qw| coding.handler.reap_children | );
    return { 'mode' => qw| false |, 'data' => 'missing job id' };
}

## hand the job to the helper [ it owns the retry logic ]
my $result = <[coding.helper.queue_depth]>->( $job_id, $job_retry_limit );

return TRUE if $result;
return FALSE;
